import{_ as o,o as d,c,a5 as a}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"gcd最大公约数","description":"在Python中， gcd 函数用于计算两个数的最大公约数（Greatest Common Divisor）。最大公约数是能同时整除两个数的最大正整数。 gcd 函数是数学和算法中的一个基本概念，它在处理分数、解决一些数学问题和算法优化中非常有用。 在Python 3.5及以上版。","frontmatter":{"title":"gcd最大公约数","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","算法训练"],"description":"在Python中， gcd 函数用于计算两个数的最大公约数（Greatest Common Divisor）。最大公约数是能同时整除两个数的最大正整数。 gcd 函数是数学和算法中的一个基本概念，它在处理分数、解决一些数学问题和算法优化中非常有用。 在Python 3.5及以上版。","sidebarWeight":2,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/算法题/HJ108 求最小公倍数/`gcd`最大公约数.md"},"headers":[],"relativePath":"posts/前端面试与实战/03-算法训练/HJ108 求最小公倍数/gcd最大公约数.md","filePath":"posts/前端面试与实战/03-算法训练/HJ108 求最小公倍数/gcd最大公约数.md"}'),t={name:"posts/前端面试与实战/03-算法训练/HJ108 求最小公倍数/gcd最大公约数.md"};function r(i,e,l,s,n,g){return d(),c("div",null,[...e[0]||(e[0]=[a('<div><h1 id="gcd最大公约数" tabindex="-1">gcd最大公约数 <a class="header-anchor" href="#gcd最大公约数" aria-label="Permalink to &quot;gcd最大公约数&quot;">​</a></h1><blockquote><p>本节目标：理解“gcd最大公约数”的核心思路，并能把它用于实际开发或面试表达。 在Python中，<code>gcd</code>函数用于计算两个数的最大公约数（Greatest Common Divisor）。最大公约数是能同时整除两个数的最大正整数。<code>gcd</code>函数是数学和算法中的一个基本概念，它在处理分数、解决一些数学问题和算法优化中非常有用。</p></blockquote><p>在Python 3.5及以上版本中，<code>gcd</code>函数可以直接通过<code>math</code>模块调用： import math</p><h1 id="计算12和16的最大公约数" tabindex="-1">计算12和16的最大公约数 <a class="header-anchor" href="#计算12和16的最大公约数" aria-label="Permalink to &quot;计算12和16的最大公约数&quot;">​</a></h1><p>result = math.gcd(12, 16) print(result) # 输出4</p><p>在上面的埃及分数分解问题中，<code>gcd</code>函数的作用是约简分数。给定分子<code>a</code>和分母<code>b</code>，通过计算它们的最大公约数，并分别除以这个最大公约数，可以得到一个等价的最简分数。这是因为分子和分母都除以它们的最大公约数后，新的分子和分母之间不再有除1以外的公约数，因此分数达到了最简形式。</p><p>例如，假设在某一步中，我们得到了分数<code>6/8</code>。<code>6</code>和<code>8</code>的最大公约数是<code>2</code>，所以我们可以把<code>6/8</code>约简为<code>(6÷2)/(8÷2) = 3/4</code>。使用<code>gcd</code>函数可以自动化这个过程，保证分解过程中的每个分数都是最简的。</p><p>def gcd(a, b): &quot;&quot;&quot;计算最大公约数（GCD）&quot;&quot;&quot; while b: a, b = b, a % b return a</p><h3 id="欧几里得算法的原理" tabindex="-1">欧几里得算法的原理 <a class="header-anchor" href="#欧几里得算法的原理" aria-label="Permalink to &quot;欧几里得算法的原理&quot;">​</a></h3><p>欧几里得算法基于一个关键的原理：两个正整数<code>a</code>和<code>b</code>（假设<code>a \\&gt; b</code>）的最大公约数与<code>b</code>和<code>a % b</code>（<code>a</code>除以<code>b</code>的余数）的最大公约数相同。换句话说，如果你不断地用较小的数去除较大的数，然后用余数再去除前一个除数，重复这个过程，直到余数为0，那么最后的除数就是这两个数的最大公约数。</p><h3 id="gcd函数的工作过程" tabindex="-1"><code>gcd</code>函数的工作过程 <a class="header-anchor" href="#gcd函数的工作过程" aria-label="Permalink to &quot;`gcd`函数的工作过程&quot;">​</a></h3><ol><li><p><strong>初始化</strong>：函数开始时接受两个参数<code>a</code>和<code>b</code>，不需要它们有特定的大小顺序，因为算法会在第一步处理中自动调整它们的位置。</p></li><li><p><strong>循环</strong>：函数内部使用<code>while</code>循环，循环的条件是<code>b</code>不等于0。在循环体内，算法执行两个操作：</p></li></ol><ul><li><strong>交换</strong>：将<code>b</code>的值赋给<code>a</code>，这相当于保留了当前的除数作为下一轮的被除数。</li><li><strong>计算余数</strong>：计算<code>a</code>除以<code>b</code>的余数，并将这个余数赋给<code>b</code>。这个步骤实现了上述的核心原理，即使用较小的数去除较大的数，并用余数继续这个过程。</li></ul><ol start="3"><li><strong>返回结果</strong>：当<code>b</code>变为0时，循环结束，此时<code>a</code>的值就是<code>a</code>和<code>b</code>的最大公约数，函数返回这个值。</li></ol><h3 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h3><p>如果<code>a = 48</code>和<code>b = 18</code>，那么算法的执行过程如下：</p><ol><li>第一次循环：<code>a = 18</code>, <code>b = 48 % 18 = 12</code></li><li>第二次循环：<code>a = 12</code>, <code>b = 18 % 12 = 6</code></li><li>第三次循环：<code>a = 6</code>, <code>b = 12 % 6 = 0</code></li></ol><p>循环结束，此时<code>a = 6</code>，所以48和18的最大公约数是6。</p><p>欧几里得算法之所以有效，是因为它将问题规模迅速缩小，直到找到最大公约数为止。这种方法对于大数也非常高效，是计算两个数最大公约数的标准方法。</p></div>',1)])])}const b=o(t,[["render",r]]);export{h as __pageData,b as default};
